<?php

namespace Tests\Unit;

use App\Support\IconSubset;
use App\Support\IconSubsetData;
use PHPUnit\Framework\TestCase;

/**
 * 1.2.3 (perf-7, perf-21, R1-071): the main CSS carries only the Font Awesome icons the site's code names, and the
 * fonts it asks for first are cut to them (resources/sass/_fontawesome.scss, resources/fonts/fontawesome and
 * app/Support/IconSubsetData.php, all generated by scripts/fontawesome/gen_site_fa_subset.py). All 1,895 icon rules
 * were 58 KB of the render-blocking main CSS, and the full fonts the layout preloaded 183 KB.
 *
 * This test reads the same sources the generator reads, with the same rules, and fails when a view, script or PHP
 * class names an icon the subset lacks: re-run the generator then (python scripts/fontawesome/gen_site_fa_subset.py,
 * from the repository root). In production an icon outside the subset still shows: the layout prints the rules of
 * the icons owners choose (IconSubset::extraCss) and resources/js/layout/icons.ts loads the full set
 * (resources/sass/fa-full.scss) for anything else.
 *
 * Neither the generator nor this test can follow a variable: a view that prints an icon from one names it as
 * fa-<name> as well (users/videos/partials/form.blade.php does so for its visibility choices).
 */
class FontAwesomeSubsetTest extends TestCase
{
    private const UTILITIES = ['fa', 'fas', 'far', 'fab', 'fa-solid', 'fa-regular', 'fa-brands', 'fa-classic', 'fa-sharp', 'fa-fw',
        'fa-spin', 'fa-pulse', 'fa-spin-pulse', 'fa-spin-reverse', 'fa-lg', 'fa-sm', 'fa-xs', 'fa-xl', 'fa-2xs', 'fa-2xl', 'fa-1x',
        'fa-2x', 'fa-3x', 'fa-4x', 'fa-5x', 'fa-6x', 'fa-7x', 'fa-8x', 'fa-9x', 'fa-10x', 'fa-beat', 'fa-fade', 'fa-beat-fade',
        'fa-bounce', 'fa-flip', 'fa-shake', 'fa-border', 'fa-pull-left', 'fa-pull-right', 'fa-pull-start', 'fa-pull-end', 'fa-li',
        'fa-ul', 'fa-stack', 'fa-stack-1x', 'fa-stack-2x', 'fa-inverse', 'fa-rotate-90', 'fa-rotate-180', 'fa-rotate-270',
        'fa-rotate-by', 'fa-flip-horizontal', 'fa-flip-vertical', 'fa-flip-both', 'fa-sr-only', 'fa-sr-only-focusable',
        'fa-width-auto', 'fa-layers', 'fa-swap-opacity'];

    public function test_every_icon_the_sites_code_names_is_in_the_subset(): void
    {
        $known = $this->glyphs();
        $subset = array_fill_keys(explode('|', IconSubsetData::SUBSET), true);
        $missing = [];

        foreach ($this->sources() as $file) {
            foreach ($this->namesIn((string) file_get_contents($file)) as $name) {
                if (isset($known[$name]) && ! isset($subset[$name])) {
                    $missing[$name][] = substr($file, strlen($this->root()) + 1);
                }
            }
        }

        // the public menus of config/menu.php (front, and the studio's user menu)
        $menu = (string) file_get_contents($this->root().'/config/menu.php');
        $public = substr($menu, (int) strpos($menu, "'front' => ["), (int) strpos($menu, "'admin' => [") - (int) strpos($menu, "'front' => ["));
        preg_match_all("/'icon'\s*=>\s*'(?:fa-)?([a-z0-9-]+)'/", $public, $menuIcons);
        $this->assertNotEmpty($menuIcons[1]);
        foreach ($menuIcons[1] as $name) {
            if (isset($known[$name]) && ! isset($subset[$name])) {
                $missing[$name][] = 'config/menu.php';
            }
        }

        ksort($missing);
        $this->assertSame([], array_map(fn (array $files) => implode(', ', array_slice(array_unique($files), 0, 3)), $missing),
            'Icons named by the code but missing from the main CSS subset: run "python scripts/fontawesome/gen_site_fa_subset.py" from the repository root');
    }

    public function test_the_stylesheet_and_the_data_class_hold_the_same_subset(): void
    {
        $scss = (string) file_get_contents($this->root().'/resources/sass/_fontawesome.scss');
        preg_match('/\$fa-icons: \((.*?)\n\);/s', $scss, $solid);
        preg_match('/\$avd-fa-brand-icons: \((.*?)\n\);/s', $scss, $brands);
        $this->assertNotEmpty($solid);
        $this->assertNotEmpty($brands);
        preg_match_all('/"([a-z0-9-]+)": \$fa-var-\1,/', $solid[1].$brands[1], $names);

        $listed = $names[1];
        sort($listed);
        $subset = explode('|', IconSubsetData::SUBSET);
        sort($subset);
        $this->assertSame($subset, $listed);
        $this->assertGreaterThan(150, count($subset));
        $this->assertLessThan(400, count($subset), 'a subset, not the whole set');

        // the package's base and utilities are still imported; the full icon list is not, nor the package's font faces
        // (R1-071: the file declares them itself, with the cut fonts)
        foreach (['core', 'sizing', 'fixed-width', 'animated', 'rotated-flipped', 'stacked', 'icons', 'screen-reader'] as $part) {
            $this->assertStringContainsString('@import "@fortawesome/fontawesome-free/scss/'.$part.'";', $scss, $part);
        }
        foreach (['fontawesome', 'solid', 'regular', 'brands'] as $part) {
            $this->assertStringNotContainsString('@import "@fortawesome/fontawesome-free/scss/'.$part.'";', $scss, $part);
        }
        $this->assertStringContainsString('$fa-font-display: swap;', $scss);
        foreach (['--#{$fa-css-prefix}-font-solid:', '--#{$fa-css-prefix}-font-regular:', '--#{$fa-css-prefix}-font-brands:', '.fas,', '.far,', '.fab,'] as $rule) {
            $this->assertStringContainsString($rule, $scss, 'the package\'s style rules and custom properties');
        }

        // the safety net's full set
        $full = (string) file_get_contents($this->root().'/resources/sass/fa-full.scss');
        foreach (['fontawesome', 'solid', 'regular', 'brands'] as $part) {
            $this->assertStringContainsString('@import "@fortawesome/fontawesome-free/scss/'.$part.'";', $full, $part);
        }
        $this->assertStringContainsString('$fa-font-display: swap;', $full);
        $this->assertStringContainsString("import('../../sass/fa-full.scss')", (string) file_get_contents($this->root().'/resources/js/layout/icons.ts'));
    }

    /**
     * R1-071: the layout preloaded the full solid (158 KB) and regular (25 KB) fonts on every page, and they competed with
     * the render-blocking CSS on slow phones. The fonts the CSS asks for first are cut to the icons the main CSS draws
     * (resources/fonts/fontawesome, generated with the subset); this fails when they lack one of its glyphs.
     */
    public function test_the_cut_fonts_hold_every_glyph_the_main_css_draws(): void
    {
        $glyphs = $this->glyphs();
        $solid = array_fill_keys(explode('|', IconSubsetData::FONT_SOLID), true);
        $regular = array_fill_keys(explode('|', IconSubsetData::FONT_REGULAR), true);
        $brands = array_fill_keys(explode('|', IconSubsetData::FONT_BRANDS), true);
        $scss = (string) file_get_contents($this->root().'/resources/sass/_fontawesome.scss');
        preg_match('/\$avd-fa-brand-icons: \((.*?)\n\);/s', $scss, $brandMap);
        preg_match_all('/"([a-z0-9-]+)": \$fa-var-\1,/', $brandMap[1] ?? '', $brandNames);
        $this->assertNotEmpty($brandNames[1]);
        $missing = [];

        foreach (explode('|', IconSubsetData::SUBSET) as $name) {
            $code = $glyphs[$name] ?? null;
            $font = in_array($name, $brandNames[1], true) ? $brands : $solid;
            if ($code === null || ! isset($font[$code])) {
                $missing[] = $name.'='.$code;
            }
        }

        // the glyphs the site's own stylesheets print in the solid font (content: "\f107"), as the generator scans them
        foreach ($this->stylesheetGlyphs() as $code => $file) {
            if (! isset($solid[$code])) {
                $missing[] = $code.' ('.$file.')';
            }
        }
        $this->assertNotEmpty($this->stylesheetGlyphs());

        $this->assertSame([], $missing, 'Glyphs the main CSS draws but the cut fonts lack: run "python scripts/fontawesome/gen_site_fa_subset.py" from the repository root');
        // Font Awesome Free's regular icons all have a solid glyph too
        $this->assertSame([], array_keys(array_diff_key($regular, $solid)));
        $this->assertGreaterThan(10, count($regular));

        // WOFF 2 files, and cuts: a fraction of the package's fonts (solid 158 KB, regular 25 KB, brands 116 KB)
        foreach (['fa-solid-900' => 48_000, 'fa-regular-400' => 15_000, 'fa-brands-400' => 15_000] as $font => $limit) {
            $path = $this->root().'/resources/fonts/fontawesome/'.$font.'.woff2';
            $this->assertFileExists($path);
            $this->assertSame('wOF2', (string) file_get_contents($path, false, null, 0, 4), $font);
            $this->assertLessThan($limit, filesize($path), $font);
        }
    }

    /**
     * R1-071: each style declares its full font first and its cut font last. The cut font's unicode-range is exactly the
     * glyphs it has (and the space, which keeps it the family's first available font: the icons' line metrics); the full
     * font's range covers every icon glyph, so an icon outside the cut (an owner's choice, an icon added without
     * re-running the generator) still shows, and leaves out white space, so a space in an icon element downloads nothing.
     */
    public function test_each_style_serves_its_cut_glyphs_from_the_cut_font_and_any_other_from_the_full_font(): void
    {
        $scss = (string) file_get_contents($this->root().'/resources/sass/_fontawesome.scss');
        preg_match_all('/@font-face \{(.*?)\n\}/s', $scss, $faces);
        $byStyle = [];
        foreach ($faces[1] as $face) {
            preg_match("/font-family: '([^']+)';/", $face, $family);
            preg_match('/font-weight: (\d+);/', $face, $weight);
            preg_match('/unicode-range: ([^;]+);/', $face, $range);
            $this->assertNotEmpty($range, 'every face has a unicode-range');
            $byStyle[$family[1].' '.$weight[1]][] = [
                'cut' => str_contains($face, "url('#{\$avd-fa-cut-path}/"),
                'full' => str_contains($face, "url('#{\$fa-font-path}/"),
                'display' => str_contains($face, 'font-display: $fa-font-display;'),
                'ranges' => $this->parseRanges($range[1]),
            ];
        }
        $this->assertSame(['Font Awesome 6 Free 900', 'Font Awesome 6 Free 400', 'Font Awesome 6 Brands 400'], array_keys($byStyle));

        $fonts = ['Font Awesome 6 Free 900' => IconSubsetData::FONT_SOLID, 'Font Awesome 6 Free 400' => IconSubsetData::FONT_REGULAR,
            'Font Awesome 6 Brands 400' => IconSubsetData::FONT_BRANDS];
        foreach ($fonts as $style => $list) {
            $this->assertCount(2, $byStyle[$style], $style);
            [$full, $cut] = $byStyle[$style];
            $this->assertTrue($full['full'] && ! $full['cut'] && $full['display'], $style.': the full font first');
            $this->assertTrue($cut['cut'] && ! $cut['full'] && $cut['display'], $style.': the cut font last');

            $codes = array_map('hexdec', explode('|', $list));
            $this->assertSame(array_merge([0x20], $codes), $this->expand($cut['ranges']), $style.': the cut font\'s range is its glyphs and the space');
            foreach ($codes as $code) {
                $this->assertTrue($this->inRanges($code, $full['ranges']), sprintf('%s: the full font\'s range covers U+%X', $style, $code));
            }
            foreach ([0x20, 0x09, 0x0A, 0xA0, 0xAD, 0x2002, 0x2009, 0x200B, 0x200D, 0x202F, 0x3000, 0xFEFF] as $space) {
                $this->assertFalse($this->inRanges($space, $full['ranges']), sprintf('%s: the full font\'s range leaves out U+%X', $style, $space));
            }
            // icons outside the cut find their full font: solid dragon (f6d5), regular face-smile (f118), brand github (f09b)
            $outside = ['Font Awesome 6 Free 900' => 0xF6D5, 'Font Awesome 6 Free 400' => 0xF118, 'Font Awesome 6 Brands 400' => 0xF09B][$style];
            $this->assertFalse($this->inRanges($outside, $cut['ranges']), $style);
            $this->assertTrue($this->inRanges($outside, $full['ranges']), $style);
        }
        // the full fonts: the package's files, as before (the safety net's full set, fa-full.scss, asks for the same)
        $this->assertStringContainsString('$fa-font-path: "../../node_modules/@fortawesome/fontawesome-free/webfonts";', $scss);
        $this->assertStringContainsString('$avd-fa-cut-path: "../fonts/fontawesome";', $scss);
    }

    public function test_owner_icons_get_exactly_their_rule(): void
    {
        $this->assertSame('', IconSubset::cssFor(['house', 'fa-house', 'fa-solid fa-house']), 'in the subset');
        $this->assertSame('.fa-dragon{--fa:"\f6d5"}', IconSubset::cssFor(['dragon']));
        $this->assertSame('.fa-dragon{--fa:"\f6d5"}', IconSubset::cssFor(['fa-solid fa-dragon', 'DRAGON ', 'dragon']), 'one rule per icon');
        $this->assertSame('', IconSubset::cssFor(['no-such-icon', '', null, 42, ['dragon']]));
        $this->assertSame('', IconSubset::cssFor(['x}body{color:red', 'dragon"}', '../dragon', 'dra gon{']), 'nothing typed reaches the stylesheet');
        $css = IconSubset::cssFor(['dragon', 'fish', 'fa-brands fa-github']);
        $this->assertSame('.fa-dragon{--fa:"\f6d5"}.fa-fish{--fa:"\f578"}.fa-github{--fa:"\f09b"}', $css);

        // R1-071: the layout preloads the full solid font only for a glyph the cut font lacks
        $this->assertTrue(IconSubset::needsFullFont($css));
        $this->assertTrue(IconSubset::needsFullFont(IconSubset::cssFor(['dragon'])));
        $this->assertFalse(IconSubset::needsFullFont(''));
        $this->assertFalse(IconSubset::needsFullFont('.fa-house{--fa:"\f015"}'), 'a glyph of the cut');
        $this->assertFalse(IconSubset::needsFullFont('.fa-x{color:red}'), 'no glyph at all');
    }

    /** @return array<string, string> code point => the first stylesheet that prints it (the generator's CSS scan) */
    private function stylesheetGlyphs(): array
    {
        $root = $this->root();
        $found = [];
        foreach (['resources/sass' => '.scss', 'resources/css' => '.css'] as $base => $extension) {
            $iterator = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root.'/'.$base, \FilesystemIterator::SKIP_DOTS));
            foreach ($iterator as $file) {
                $relative = substr(str_replace('\\', '/', $file->getPathname()), strlen($root) + 1);
                if (! str_ends_with($relative, $extension) || str_starts_with($relative, 'resources/css/themes/')
                    || in_array($relative, ['resources/sass/_fontawesome.scss', 'resources/sass/fa-full.scss'], true)) {
                    continue;
                }
                preg_match_all('/content\s*:\s*["\']\\\\([ef][0-9a-fA-F]{3})["\']/', (string) file_get_contents($file->getPathname()), $m);
                foreach ($m[1] as $code) {
                    $found[strtolower($code)] ??= $relative;
                }
            }
        }
        ksort($found);

        return $found;
    }

    /** @return list<array{0: int, 1: int}> "U+20, U+F002-F005" as [first, last] pairs */
    private function parseRanges(string $css): array
    {
        $ranges = [];
        foreach (explode(',', $css) as $part) {
            $this->assertMatchesRegularExpression('/^U\+[0-9A-F]+(?:-[0-9A-F]+)?$/', trim($part));
            $bounds = explode('-', substr(trim($part), 2));
            $ranges[] = [(int) hexdec($bounds[0]), (int) hexdec($bounds[1] ?? $bounds[0])];
        }

        return $ranges;
    }

    /** @param  list<array{0: int, 1: int}>  $ranges @return list<int> */
    private function expand(array $ranges): array
    {
        $points = [];
        foreach ($ranges as [$first, $last]) {
            $points = array_merge($points, range($first, $last));
        }
        sort($points);

        return $points;
    }

    /** @param  list<array{0: int, 1: int}>  $ranges */
    private function inRanges(int $point, array $ranges): bool
    {
        foreach ($ranges as [$first, $last]) {
            if ($point >= $first && $point <= $last) {
                return true;
            }
        }

        return false;
    }

    /** @return array<string, string> */
    private function glyphs(): array
    {
        $glyphs = [];
        foreach (explode('|', IconSubsetData::GLYPHS) as $pair) {
            [$name, $code] = explode('=', $pair, 2);
            $glyphs[$name] = $code;
        }

        return $glyphs;
    }

    /** The generator's sources: the public views, the scripts, the PHP code (not the admin's own pages and controllers). */
    private function sources(): array
    {
        $root = $this->root();
        $files = [];
        $scan = [
            ['resources/views', ['.blade.php'], ['resources/views/admin', 'resources/views/components/admin']],
            ['resources/js', ['.ts', '.tsx', '.js'], []],
            ['app', ['.php'], ['app/Http/Controllers/Admin']],
        ];
        foreach ($scan as [$base, $extensions, $skip]) {
            $iterator = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root.'/'.$base, \FilesystemIterator::SKIP_DOTS));
            foreach ($iterator as $file) {
                $path = str_replace('\\', '/', $file->getPathname());
                $relative = substr($path, strlen($root) + 1);
                if (array_filter($skip, fn ($s) => str_starts_with($relative, $s.'/')) !== []) {
                    continue;
                }
                if (array_filter($extensions, fn ($e) => str_ends_with($path, $e)) === [] || str_ends_with($path, 'app/Support/IconSubsetData.php')) {
                    continue;
                }
                $files[] = $path;
            }
        }
        $draft = $root.'/resources/views/admin/appearance/partials/draft-banner.blade.php';
        if (is_file($draft)) {
            $files[] = $draft;
        }

        return $files;
    }

    /** @return list<string> the generator's rules: fa-<name>, the quoted names of fa-{{ }} / fa-${}, icon lines, icon(). */
    private function namesIn(string $source): array
    {
        $names = [];
        preg_match_all('/(?<![\w-])fa-([a-z0-9](?:[a-z0-9-]*[a-z0-9])?)(?![\w-])/', $source, $m);
        $names = array_merge($names, $m[1]);
        preg_match_all('/fa-\{\{(.*?)\}\}|fa-\$\{(.*?)\}/s', $source, $dynamic);
        foreach (array_merge($dynamic[1], $dynamic[2]) as $expression) {
            preg_match_all('/[\'"`]([a-z0-9][a-z0-9-]*)[\'"`]/', $expression, $q);
            $names = array_merge($names, $q[1]);
        }
        foreach (preg_split('/\R/', $source) ?: [] as $line) {
            if (stripos($line, 'icon') !== false) {
                preg_match_all('/[\'"`]([a-z0-9][a-z0-9-]*)[\'"`]/', $line, $q);
                $names = array_merge($names, $q[1]);
            }
        }
        preg_match_all('/function icon\(\)[^{]*\{(.*?)\n\s*\}/s', $source, $bodies);
        foreach ($bodies[1] as $body) {
            preg_match_all('/[\'"`]([a-z0-9][a-z0-9-]*)[\'"`]/', $body, $q);
            $names = array_merge($names, $q[1]);
        }

        return array_values(array_filter(array_unique($names), fn ($n) => ! in_array('fa-'.$n, self::UTILITIES, true) && ! in_array($n, ['solid', 'regular', 'brands'], true)));
    }

    private function root(): string
    {
        return str_replace('\\', '/', dirname(__DIR__, 2));
    }
}
